WHERE (
    batches.scope_type = 'PLATFORM'

        OR organizations.organization_code IN

            #{code}


)


    AND organizations.organization_code = #{query.organizationCode}



    AND batches.request_key = #{query.requestKey}



    AND batches.data_category = #{query.category}



    AND batches.batch_status = #{query.status}



    AND batches.started_at >= #{query.startedFromUtc}



    AND batches.started_at <= #{query.startedToUtc}

mapper.select:

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM md_medical_directory directory
    INNER JOIN md_sync_batch latest ON latest.id = directory.latest_batch_id
    WHERE directory.organization_id = #{organizationId}
      AND latest.environment_code <> #{environment}
) THEN 1 ELSE 0 END


SELECT 
FROM md_sync_batch batches
LEFT JOIN org_organization organizations ON organizations.id = batches.organization_id
WHERE batches.id = #{id}
  AND (
    batches.scope_type = 'PLATFORM'

        OR organizations.organization_code IN

            #{code}


  )


SELECT CASE WHEN EXISTS (
    SELECT 1 FROM md_sync_batch WITH (UPDLOCK, HOLDLOCK)
    WHERE id = #{batchId} AND row_version = #{expectedVersion}
      AND batch_status IN ('FETCHING', 'RESULT_UNKNOWN')
) THEN 1 ELSE 0 END

mapper.update:
